69	pub enum NoScriptUrlState {
70	    JsxAttribute(TextRange),
71	    ReactProp(TextRange),
72	}
73	
74	impl NoScriptUrlState {
75	    fn range(&self) -> TextRange {
76	        match self {
77	            Self::JsxAttribute(range) | Self::ReactProp(range) => *range,
78	        }
79	    }
80	}
