    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// setTimeout("alert('Hi!');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// setInterval("alert('Hi!');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// setImmediate("alert('Hi!')");
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// window.setTimeout("count = 5", 10);
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// setTimeout(function () {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    ///
    /// ```js
    /// setInterval(() => {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    ///
    /// ```js
    /// setTimeout(fn, 100);
    /// ```
    ///
    pub NoImpliedEval {
        version: "next",
        name: "noImpliedEval",
        language: "js",
        recommended: false,
        severity: Severity::Error,
    }
}

/// The functions that trigger an implied `eval()` when passed a string.
const IMPLIED_EVAL_FUNCTIONS: [&str; 3] = ["setTimeout", "setInterval", "setImmediate"];

impl Rule for NoImpliedEval {
    type Query = Semantic<JsCallExpression>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoImpliedEvalOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();
        let model = ctx.model();

        let callee = node.callee().ok()?.omit_parentheses();

        // Resolve the callee to a global identifier. This handles direct calls
        // (`setTimeout`) as well as accesses through `window` or `globalThis`
        // (including optional chaining and chained global accesses like
        // `window.window.setTimeout`). It returns `None` for member chains that
        // go deeper than one level on a global (e.g. `window.foo.setTimeout`) or
        // for methods on non-global objects (e.g. `obj.setTimeout`).
        let (reference, name) = global_identifier(&callee)?;

        if !IMPLIED_EVAL_FUNCTIONS.contains(&name.text()) {
            return None;
        }

        // Ignore the call when the identifier resolves to a local binding, i.e.
        // when the function name (or the `window`/`globalThis` object) has been
        // shadowed by a local parameter or variable.
        if model.binding(&reference).is_some() {
            return None;
        }

        let first_argument = node.arguments().ok()?.args().first()?.ok()?;
        let first_argument = first_argument.as_any_js_expression()?;

        if is_string_expression(first_argument) {
            Some(())
        } else {
            None
        }
    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "Implied eval() is not allowed."
                },
            )
            .note(markup! {
                "Passing strings to functions like setTimeout, setInterval, or setImmediate is a form of implied eval() and can lead to security and performance issues."
            })
            .note(markup! {
                "Use a function instead of a string."
            }),
        )
    }
}

/// Returns `true` when `expr` is a string expression: a string literal, a
/// template literal without any substitutions, or a `+` concatenation where at
/// least one operand is a string expression.
fn is_string_expression(expr: &AnyJsExpression) -> bool {
    let expr = expr.clone().omit_parentheses();
    match &expr {
        AnyJsExpression::AnyJsLiteralExpression(literal) => {
            literal.as_js_string_literal_expression().is_some()
        }
        AnyJsExpression::JsTemplateExpression(template) => !template
            .elements()
            .into_iter()
            .any(|element| matches!(element, AnyJsTemplateElement::JsTemplateElement(_))),
        AnyJsExpression::JsBinaryExpression(binary) => {
            if binary.operator().ok() != Some(JsBinaryOperator::Plus) {
                return false;
            }
            let (Ok(left), Ok(right)) = (binary.left(), binary.right()) else {
                return false;
            };
            is_string_expression(&left) || is_string_expression(&right)
        }
        _ => false,
    }
}
